using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
public static class SmallPropsChecks {
 [Serializable] class Check{public string name;public bool pass;public string detail;}
 [Serializable] class Report{public bool pass;public string unity,gpu;public List<Check> checks;}
 static List<Check> checks=new List<Check>();static void Verify(string n,bool v,string detail=""){checks.Add(new Check{name=n,pass=v,detail=detail});if(!v)throw new Exception(n+": "+detail);}
 static string Arg(string key){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,key)+1];}
 public static void Run(){var output=Arg("-props-output");var source=Arg("-props-export");int code=0;try{
  Directory.CreateDirectory(output);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var data=SmallPropsV1.Read(Path.Combine(source,"small_props.json"));var built=MapSharedPropsBuilder.Build(source);Verify("all nineteen current small props have real Unity prefabs",Array.TrueForAll(data.assets,a=>built.prefabs.ContainsKey(a.id)));
  foreach(var a in data.assets){var o=built.prefabs[a.id];var mesh=o.GetComponent<MeshFilter>().sharedMesh;var pos=mesh.vertices;var ns=mesh.normals;var colors=mesh.colors;float error=0,colorError=0;for(int k=0;k<pos.Length;k++){error=Mathf.Max(error,Vector3.Distance(pos[k],new Vector3(a.positions[k*3],a.positions[k*3+1],a.positions[k*3+2])),Vector3.Distance(ns[k],new Vector3(a.normals[k*3],a.normals[k*3+1],a.normals[k*3+2])));colorError=Mathf.Max(colorError,Mathf.Abs(colors[k].r-a.colors[k*3]),Mathf.Abs(colors[k].g-a.colors[k*3+1]),Mathf.Abs(colors[k].b-a.colors[k*3+2]));}Verify(a.id+" exact exported mesh",error<.000001f&&colorError<.000001f&&mesh.triangles.Length==a.triangles.Length,"max error "+error);Verify(a.id+" one opaque material and preserved collider presence",o.GetComponent<Renderer>().sharedMaterials.Length==1&&((o.GetComponent<MeshCollider>()!=null)==(a.radius>0)));}
  Verify("nineteen fixture placements imported",built.placed==19&&built.skipped==0,"placed="+built.placed+", skipped="+built.skipped);Verify("two independently selectable column prefabs",built.prefabs["brokencol_base"]!=built.prefabs["columnfragment"]);Verify("legacy composite remains importable",built.prefabs.ContainsKey("brokencol"));
  foreach(Transform child in built.root.transform)child.gameObject.SetActive(false);
  var rd=ScriptableObject.CreateInstance<UniversalRendererData>();var rp=UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=30;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.35f,.35f);var sun=new GameObject("Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2.1f;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(-5,-9,-4));
  var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.transform.localScale=Vector3.one*3;var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.SetColor("_BaseColor",new Color(.22f,.17f,.11f));floor.GetComponent<Renderer>().sharedMaterial=fm;
  var camera=new GameObject("Small props proof camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.fieldOfView=50;camera.aspect=1.28f;camera.backgroundColor=Color.black;camera.clearFlags=CameraClearFlags.SolidColor;var rt=new RenderTexture(1280,1000,24,RenderTextureFormat.ARGB32);camera.targetTexture=rt;
  foreach(var a in data.assets){var o=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[a.id]);o.transform.position=Vector3.down*a.groundSink;foreach(string view in new[]{"top","detail"}){float target=a.id.StartsWith("statue")?1.3f:a.id=="brokencol"||a.id=="brokencol_base"?.7f:.2f;float d=a.id.StartsWith("statue")?5.8f:a.id.StartsWith("brokencol")?4:2.8f;camera.transform.position=view=="top"?new Vector3(0,17,0):new Vector3(d*.6f,target+d*.35f,-d*.8f);camera.transform.rotation=Quaternion.LookRotation(new Vector3(0,target,0)-camera.transform.position,view=="top"?Vector3.forward:Vector3.up);camera.Render();RenderTexture.active=rt;var png=new Texture2D(1280,1000,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,1280,1000),0,0);png.Apply();File.WriteAllBytes(Path.Combine(output,a.id+"-"+view+".png"),png.EncodeToPNG());UnityEngine.Object.DestroyImmediate(png);RenderTexture.active=null;}UnityEngine.Object.DestroyImmediate(o);}
  Verify("D3D11 actual renders completed",SystemInfo.graphicsDeviceType==GraphicsDeviceType.Direct3D11,"gpu="+SystemInfo.graphicsDeviceName);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/SmallPropsProof.unity");AssetDatabase.SaveAssets();
 }catch(Exception e){checks.Add(new Check{name="exception",pass=false,detail=e.ToString()});Debug.LogException(e);code=1;}finally{File.WriteAllText(Path.Combine(output,"report.json"),JsonUtility.ToJson(new Report{pass=code==0,unity=Application.unityVersion,gpu=SystemInfo.graphicsDeviceName,checks=checks},true));EditorApplication.Exit(code);}}
}
